1::root{color-scheme:dark;--bg:#101114;--panel:#191a1f;--panel-2:#202127;--line:#303137;--muted:#85858f;--text:#f4f3ef;--lime:#d2f36b;--pink:#fb7185;--font:'Space Grotesk',sans-serif;--mono:'DM Mono',monospace}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 75% 4%,rgba(210,243,107,.055),transparent 30%),var(--bg);color:var(--text);font-family:var(--font);min-height:100vh}.app-shell{max-width:1160px;margin:0 auto;padding:0 40px}.topbar{height:74px;border-bottom:1px solid #ffffff13;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;font-size:16px;letter-spacing:1.6px;font-weight:700;color:var(--text);text-decoration:none}.brand-mark{background:var(--lime);color:#171a0d;border-radius:7px;width:28px;height:28px;display:grid;place-items:center;font-size:17px;font-weight:700}.brand-dot{color:var(--lime)}.top-meta,.eyebrow,.optional-tag,.round-count,.tempo-status,.bpm-unit,.prompt-topline,.rhyme-heading,.tempo-controls>label,.text-button,.session-stats div span,.page-footer,.local-badge{font-family:var(--mono);letter-spacing:1px}.top-meta{color:#8e8f91;font-size:10px;display:flex;align-items:center;gap:8px}.live-dot,.status-dot,.local-badge i{width:7px;height:7px;background:var(--lime);border-radius:50%;box-shadow:0 0 10px #d2f36b65}.icon-button{width:34px;height:34px;background:#202127;border:1px solid var(--line);border-radius:9px;color:#c5c6cb;cursor:pointer;font-size:19px}.icon-button.active{color:var(--lime);border-color:#d2f36b70}.intro{padding:42px 0 30px}.eyebrow{font-size:9px;color:#a6a6ad;margin:0 0 11px}.intro h1{font-size:clamp(34px,5vw,47px);letter-spacing:-2.3px;line-height:1;margin:0}.intro h1 span{color:var(--lime)}.intro-copy{margin:12px 0 0;color:#96969e;font-size:13px;max-width:540px;line-height:1.6}.studio-grid{display:grid;grid-template-columns:minmax(0,1.48fr) minmax(310px,.82fr);gap:18px;align-items:stretch}.left-column{display:flex;flex-direction:column;gap:18px}.card{background:linear-gradient(145deg,#1b1c21,#18191e);border:1px solid #ffffff10;border-radius:14px;padding:20px;box-shadow:0 16px 38px #00000014}.card-heading{display:flex;justify-content:space-between;align-items:flex-start}.card-heading h2{margin:0;font-size:17px;letter-spacing:-.4px}.optional-tag,.round-count{border:1px solid #ffffff18;border-radius:30px;padding:6px 9px;font-size:8px;color:#999aa2}.youtube-form{display:flex;gap:8px;margin-top:16px}.youtube-form input{flex:1;min-width:0;background:#111216;border:1px solid #35363c;border-radius:8px;padding:0 12px;color:var(--text);font:12px var(--font);outline:none}.youtube-form input:focus{border-color:var(--lime)}.youtube-form input::placeholder{color:#70717a}.button{border:0;border-radius:8px;padding:0 14px;font:700 10px var(--mono);letter-spacing:.5px;cursor:pointer}.button-light{background:#e8e8e3;color:#17181b;height:38px}.button-light:hover{background:var(--lime)}.helper-text{font-size:10px;color:#82838b;margin:10px 0 0;line-height:1.5}.player-frame{position:relative;margin-top:14px;border-radius:9px;overflow:hidden;background:#0d0e11;aspect-ratio:16/9}.player-frame[hidden]{display:none}.player-frame iframe{width:100%;height:100%;border:0}.player-close{position:absolute;right:7px;top:7px;width:27px;height:27px;border:0;border-radius:50%;background:#000a;color:white;font-size:20px;cursor:pointer}.challenge-card{flex:1}.mode-switch{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:17px 0}.mode-button{display:flex;align-items:center;text-align:left;gap:10px;padding:11px 12px;background:#202127;border:1px solid #ffffff0d;border-radius:9px;color:#b8b8bf;cursor:pointer;transition:.18s}.mode-button:hover{border-color:#ffffff32}.mode-button.active{border-color:#d2f36b66;background:#25291e;color:#f4f3ef}.mode-icon{display:grid;place-items:center;width:34px;height:34px;border-radius:8px;background:#2c2d33;color:var(--lime);font-weight:700;font-size:16px}.mode-button strong,.mode-button small{display:block}.