182:       if (interval > LONG_PAUSE) {
183:         state.intervals = [];
184:         state.pendingIntervals = [];
185:       } else if (interval >= MIN_TAP_INTERVAL && interval <= MAX_TAP_INTERVAL) {
186:         acceptTapInterval(interval);
187:       } else {
188:         state.pendingIntervals = [];
189:       }
190:     }
191:     state.lastTapAt = now;
192: 
193:     if (!state.bpm) {
