201:   function acceptTapInterval(interval) {
202:     const baseline = median(state.intervals);
203:     if (!baseline || Math.abs(interval - baseline) <= baseline * OUTLIER_TOLERANCE) {
204:       state.intervals.push(interval);
205:       state.intervals = state.intervals.slice(-6);
206:       state.pendingIntervals = [];
207:     } else {
208:       const pendingBaseline = median(state.pendingIntervals);
209:       if (!pendingBaseline || Math.abs(interval - pendingBaseline) > pendingBaseline * OUTLIER_TOLERANCE) {
210:         state.pendingIntervals = [interval];
211:       } else {
212:         state.pendingIntervals.push(interval);
213:         if (state.pendingIntervals.length >= 2) {
214:           state.intervals = state.pendingIntervals.slice(-6);
215:           state.pendingIntervals = [];
216:         }
217:       }
218:     }
