220:     if (!state.intervals.length) return;
221:     const previousBpm = state.bpm;
222:     const estimate = estimateBpm(state.intervals);
223:     state.bpm = estimate;
224:     ui.bpm.textContent = String(estimate);
225:     ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
