313:   function scheduleLoop(generation) {
314:     if (!state.running || generation !== state.generation) return;
315:     const now = performance.now();
316:     if (state.nextTickAt < now - MAX_CLOCK_LATENESS_MS) {
317:       clearClockTimers();
318:       state.tickNumber = Math.max(0, state.lastTickNumber + 1);
319:       state.nextTickAt = now + 8;
320:     }
321:     while (state.nextTickAt <= now + CLOCK_LOOKAHEAD_MS) {
322:       const scheduledAt = state.nextTickAt;
323:       const tick = state.tickNumber++;
324:       const grid = clockGrid(tick);
325:       queueTick(scheduledAt, tick, grid, generation);
326:       if (state.soundOn) scheduleClick(scheduledAt, grid.isAccent);
327:       state.nextTickAt += grid.stepMs;
