463:     while (state.fiveDeck.length < 5) {
464:       const currentWords = new Set(state.currentPrompt?.words || []);
465:       const available = FIVE_WORDS.filter((word) => !state.fiveDeck.includes(word) && !currentWords.has(word));
466:       const fallback = FIVE_WORDS.filter((word) => !state.fiveDeck.includes(word));
467:       state.fiveDeck.push(...shuffle(available.length ? available : fallback));
468:       if (!state.fiveDeck.length) break;
469:     }
470:     return state.fiveDeck.splice(0, 5);
