476:     const deck = state.decks[mode];
477:     if (!deck.length) {
478:       const fresh = pool.filter((item) => item !== state.currentPrompt);
479:       deck.push(...shuffle(fresh.length ? fresh : pool));
480:     }
481:     return deck.shift() || pool[0];
482:   }
