484:   function shuffle(items) {
485:     const copy = [...items];
486:     for (let index = copy.length - 1; index > 0; index -= 1) {
487:       const swapWith = Math.floor(Math.random() * (index + 1));
488:       [copy[index], copy[swapWith]] = [copy[swapWith], copy[index]];
489:     }
490:     return copy;
491:   }
