174:   function handleTap() {
175:     const now = performance.now();
176:     const hadPreviousTap = state.lastTapAt !== null;
177:     pulseTapButton();
178:     if (state.soundOn) resumeAudio();
179: 
180:     if (state.lastTapAt !== null) {
181:       const interval = now - state.lastTapAt;
182:       if (interval > LONG_PAUSE) {
183:         state.intervals = [];
184:         state.pendingIntervals = [];
185:       } else if (interval >= MIN_TAP_INTERVAL && interval <= MAX_TAP_INTERVAL) {
186:         acceptTapInterval(interval);
187:       } else {
188:         state.pendingIntervals = [];
189:       }
190:     }
191:     state.lastTapAt = now;
192: 
193:     if (!state.bpm) {
194:       ui.tempoCaption.textContent = hadPreviousTap
195:         ? 'Seguí tocando para fijar el pulso'
196:         : 'Tocá al ritmo de tu base';
197:     }
198:     if (state.vibrationOn) requestTapVibration();
