231:   function median(values) {
232:     if (!values.length) return null;
233:     const ordered = [...values].sort((a, b) => a - b);
234:     const middle = Math.floor(ordered.length / 2);
235:     return ordered.length % 2 ? ordered[middle] : (ordered[middle - 1] + ordered[middle]) / 2;
236:   }
