290:   function adjustClockTempo() {
291:     const now = performance.now();
292:     const oldStepMs = state.clockStepMs || clockGrid(0).stepMs;
293:     const phase = state.lastTickAt === null
294:       ? 0
295:       : Math.max(0, Math.min(1, (now - state.lastTickAt) / oldStepMs));
296:     state.generation += 1;
297:     clearClockTimers();
298:     state.clockStepMs = clockGrid(0).stepMs;
299:     if (state.lastTickNumber < 0) {
300:       state.tickNumber = 0;
301:       state.nextTickAt = now + 70;
302:     } else {
303:       state.tickNumber = state.lastTickNumber + 1;
304:       state.nextTickAt = now + Math.max(8, state.clockStepMs * (1 - phase));
305:     }
306:     scheduleLoop(state.generation);
307:   }
