337:       if (tick <= state.lastTickNumber) return;
338:       if (performance.now() - time > Math.min(state.clockStepMs, MAX_CLOCK_LATENESS_MS)) return;
339:       state.lastTickNumber = tick;
340:       state.lastTickAt = time;
341:       renderBeat(grid.beat, grid.isAccent);
342:       if (grid.isAccent) onMainBeat(grid.beat);
343:     }, delay);
344:     state.tickTimerIds.add(id);
345:   }
